package com.ledgerly;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDate;
@MappedSuperclass class UserAccount {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String name; @Column(nullable=false,unique=true) public String email; @Column(nullable=false) public String passwordHash; public UserAccount(){} public UserAccount(String n,String e,String p){name=n;email=e;passwordHash=p;}}
@Entity @Table(name="users") class UserEntity extends UserAccount { public UserEntity(){} public UserEntity(String n,String e,String p){super(n,e,p);} }
@Entity @Table(name="transactions") class TransactionEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) public UserEntity user; @Column(nullable=false,precision=12,scale=2) public BigDecimal amount; @Column(nullable=false) public String type; @Column(nullable=false) public String category; @Column(nullable=false) public LocalDate date; @Column(length=240) public String description; public TransactionEntity(){} }
@Entity @Table(name="monthly_budgets",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","monthKey"})) class BudgetEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) public UserEntity user; @Column(nullable=false) public String monthKey; @Column(nullable=false,precision=12,scale=2) public BigDecimal amount; public BudgetEntity(){} }
